    <?php if ($errors): ?><div class="form-errors admin-form-errors" role="alert"><strong>No pudimos guardar el contenido:</strong><ul><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach ?></ul></div><?php endif ?>
    <?php if ($preview): ?><p class="demo-form-note admin-form-note"><?= cf_icon('info') ?>Vista de muestra. Los datos y las cargas están desactivados.</p><?php endif ?>
    <form class="content-form" action="<?= e(url('/admin/guardar')) ?>" method="post" data-validate><?= csrf_field() ?><input type="hidden" name="q" value="<?= e($adminQuery) ?>"><input type="hidden" name="pagina" value="<?= (int) $listPage ?>"><fieldset <?= $preview ? 'disabled' : '' ?>><?php if ($editingMovie): ?><input type="hidden" name="id" value="<?= (int) $editingMovie['id'] ?>"><?php endif ?><div class="form-grid"><div class="field span-two"><label for="titulo">Título de la película <span>*</span></label><input id="titulo" name="titulo" type="text" placeholder="Toda gran historia tiene un nombre" maxlength="255" value="<?= e($formMovie['titulo'] ?? '') ?>" required></div><div class="field"><label for="categoria_id">Categoría <span>*</span></label><select id="categoria_id" name="categoria_id" required><option value="">Selecciona una categoría</option><?php foreach ($categories as $cat): ?><option value="<?= (int) $cat['id'] ?>" <?= (string) ($formMovie['categoria_id'] ?? '') === (string) $cat['id'] ? 'selected' : '' ?>><?= e($cat['nombre']) ?></option><?php endforeach ?></select></div><div class="field"><label for="fechalanzamiento">Año de estreno <span>*</span></label><input id="fechalanzamiento" name="fechalanzamiento" type="number" min="1888" max="<?= (int) date('Y') + 1 ?>" placeholder="1930" value="<?= e($formMovie['fechalanzamiento'] ?? '') ?>" required></div><div class="field"><label for="duracion">Duración de la película, en segundos <span>*</span></label><input id="duracion" name="duracion" type="number" min="1" max="86400" required placeholder="5400" value="<?= e($formMovie['duracion'] ?? '') ?>"><small class="field-hint">Por ejemplo, 90 minutos = 5400 segundos.</small></div><div class="field"><label for="trailer_duracion">Duración del tráiler, en segundos <span>*</span></label><input id="trailer_duracion" name="trailer_duracion" type="number" min="1" max="86400" required placeholder="120" value="<?= e($formMovie['trailer_duracion'] ?? '') ?>"></div><div class="field"><label for="director">Dirección</label><input id="director" name="director" type="text" maxlength="100" placeholder="Nombre del director o directora" value="<?= e($formMovie['director'] ?? '') ?>"></div><div class="field"><label for="actores">Reparto principal</label><input id="actores" name="actores" type="text" maxlength="255" placeholder="Nombres separados por comas" value="<?= e($formMovie['actores'] ?? '') ?>"></div><div class="field span-two"><label for="sinopsis">Sinopsis <span>*</span></label><textarea id="sinopsis" name="sinopsis" rows="4" maxlength="10000" placeholder="Una pequeña invitación a descubrir esta historia…" required><?= e($formMovie['sinopsis'] ?? '') ?></textarea></div><div class="field"><label for="estado">Estado de publicación</label><select id="estado" name="estado"><option value="borrador" <?= ($formMovie['estado'] ?? '') !== 'publicado' ? 'selected' : '' ?>>Borrador</option><option value="publicado" <?= ($formMovie['estado'] ?? '') === 'publicado' ? 'selected' : '' ?>>Publicado</option></select><small class="field-hint">Para publicar se necesitan portada y tráiler cargados.</small></div></div><div class="form-actions"><p><?= $editingMovie ? 'Guarda los cambios antes de continuar con los archivos.' : 'Primero guarda el borrador. Después podrás cargar los archivos.' ?></p><button class="button button-gold" type="submit"><?= cf_icon('check') ?> <?= $editingMovie ? 'Guardar cambios' : 'Guardar borrador' ?></button></div></fieldset></form>
